# Brute-force check: no 3,4,5-cycles
def has_cycle_of_length(edges, n, k):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # DFS looking for cycles of exactly length k
    def dfs(start, current, path, depth):
        if depth == k:
            return start in adj[current]
        for nb in adj[current]:
            if nb != path[-2] if len(path) >= 2 else True:  # no immediate backtrack
                if nb not in path[1:]:  # don't revisit (except start)
                    if dfs(start, nb, path + [nb], depth + 1):
                        return True
        return False

    for start in range(n):
        if dfs(start, start, [start], 0):
            return True
    return False

for k in [3, 4, 5]:
    found = has_cycle_of_length(edges, n, k)
    print(f"Has {k}-cycle: {found}")

